def summarize_ranges(nums: list[int]) -> str:
    nums = sorted(set(nums))
    if not nums:
        return ""

    result = []
    i = 0

    while i < len(nums):
        start = nums[i]
        end = start
        j = i + 1

        while j < len(nums) and nums[j] == nums[j - 1] + 1:
            end = nums[j]
            j += 1

        if j - i >= 3:
            result.append(f"{start}..{end}")
        else:
            result.extend(str(num) for num in nums[i:j])

        i = j

    return ",".join(result)
